using Jindan.Contracts;
using Jindan.Core;
using Jindan.Core.Sync;

static partial class Program
{
    sealed class TestClock : IWorkspaceSyncClock70
    {
        readonly System.Collections.Concurrent.ConcurrentQueue<TaskCompletionSource> waiting = new();
        public List<TimeSpan> Delays { get; } = [];
        public Task DelayAsync(TimeSpan delay, CancellationToken ct) { var done = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously); lock (Delays) Delays.Add(delay); waiting.Enqueue(done); return done.Task.WaitAsync(ct); }
        public void Tick() { Check(waiting.TryDequeue(out var done), "No scheduled tick"); done!.TrySetResult(); }
    }
    sealed class ScheduledFixture : IWorkspaceSyncService
    {
        public bool Configured = true; public int StatusCalls, PushCalls, Pending = 1;
        public Func<CancellationToken, Task>? BeforePush; public bool FailPush, Revoke;
        public List<string?> Projects = [];
        public Task<WorkspaceSyncStatus> StatusAsync(string? projectId = null, CancellationToken ct = default) { ct.ThrowIfCancellationRequested(); StatusCalls++; if (Revoke) throw new WorkspaceException("UNAUTHENTICATED", "Synthetic session expired"); return Task.FromResult(new WorkspaceSyncStatus("explicit-scheduler-fixture", Configured, true, Pending == 0 ? [] : [new("revision", "projects", "item", "synthetic", projectId, "upsert", 1, DateTimeOffset.UtcNow)], null)); }
        public async Task<WorkspaceSyncResult> PushPendingAsync(string? projectId, bool explicitlyConfirmed, CancellationToken ct = default) { Check(explicitlyConfirmed); PushCalls++; Projects.Add(projectId); if (BeforePush is not null) await BeforePush(ct); ct.ThrowIfCancellationRequested(); if (FailPush) throw new IOException("Sensitive remote text must not reach state"); Pending = 0; return new(1, 1, [], true); }
    }
    static async Task Eventually(Func<bool> predicate) { using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(5)); while (!predicate()) await Task.Delay(10, timeout.Token); }
    static async Task SchedulerTests()
    {
        await Run("scheduler is disabled by default and unconfigured startup makes no push", async () => { var service = new ScheduledFixture { Configured = false }; var clock = new TestClock(); await using var scheduler = new WorkspaceSyncScheduler70(service, clock); Check(!scheduler.State.Running && service.StatusCalls == 0 && service.PushCalls == 0); await Expect("CONFIRMATION", () => scheduler.StartAsync("p", false, TimeSpan.FromMinutes(1))); await Expect("PRODUCTION_NOT_CONFIGURED", () => scheduler.StartAsync("p", true, TimeSpan.FromMinutes(1))); Check(service.PushCalls == 0 && clock.Delays.Count == 0); });
        await Run("scheduler opt-in fake clock sends current pending once then idles without empty pushes", async () => { var service = new ScheduledFixture(); var clock = new TestClock(); await using var scheduler = new WorkspaceSyncScheduler70(service, clock); await scheduler.StartAsync("p", true, TimeSpan.FromMinutes(1)); Check(service.PushCalls == 0); clock.Tick(); await Eventually(() => clock.Delays.Count == 2); Check(service.PushCalls == 1 && scheduler.State.Code == "ACKNOWLEDGED"); clock.Tick(); await Eventually(() => clock.Delays.Count == 3); Check(service.PushCalls == 1 && scheduler.State.Code == "IDLE"); });
        await Run("scheduler offline skips transport and bounded retries use injected clock", async () => { var online = false; var service = new ScheduledFixture { FailPush = true }; var clock = new TestClock(); await using var scheduler = new WorkspaceSyncScheduler70(service, clock, () => online); await scheduler.StartAsync("p", true, TimeSpan.FromMinutes(1)); clock.Tick(); await Eventually(() => clock.Delays.Count == 2); Check(service.PushCalls == 0 && scheduler.State.Code == "OFFLINE"); online = true; clock.Tick(); await Eventually(() => clock.Delays.Count == 3); Check(service.PushCalls == 1 && scheduler.State.Code == "RETRY_PENDING" && clock.Delays[2] == TimeSpan.FromMinutes(2)); clock.Tick(); await Eventually(() => clock.Delays.Count == 4); Check(clock.Delays[3] == TimeSpan.FromMinutes(4)); clock.Tick(); await Eventually(() => clock.Delays.Count == 5); Check(clock.Delays[4] == TimeSpan.FromMinutes(5)); service.FailPush = false; clock.Tick(); await Eventually(() => clock.Delays.Count == 6); Check(scheduler.State.Code == "ACKNOWLEDGED" && clock.Delays[5] == TimeSpan.FromMinutes(1)); });
        await Run("scheduler cancellation waits for owned cooperative push and generation prevents stale context result", async () => { var service = new ScheduledFixture(); var entered = new TaskCompletionSource(); service.BeforePush = async ct => { entered.TrySetResult(); await Task.Delay(Timeout.Infinite, ct); }; var clock = new TestClock(); await using var scheduler = new WorkspaceSyncScheduler70(service, clock); await scheduler.StartAsync("project-a", true, TimeSpan.FromMinutes(1)); clock.Tick(); await entered.Task; var generation = scheduler.State.Generation; await scheduler.StopAsync(); Check(!scheduler.State.Running && scheduler.State.Generation > generation && service.Pending == 1); service.BeforePush = null; await scheduler.StartAsync("project-b", true, TimeSpan.FromMinutes(1)); clock.Tick(); await Eventually(() => scheduler.State.Code == "ACKNOWLEDGED"); Check(service.Projects.SequenceEqual(new[] { "project-a", "project-b" }) && scheduler.State.ProjectId == "project-b"); });
        await Run("scheduler session revocation stops loop and never reuses failed auth", async () => { var service = new ScheduledFixture(); var clock = new TestClock(); await using var scheduler = new WorkspaceSyncScheduler70(service, clock); await scheduler.StartAsync("p", true, TimeSpan.FromMinutes(1)); service.Revoke = true; clock.Tick(); await Eventually(() => !scheduler.State.Running); Check(scheduler.State.Code == "UNAUTHENTICATED" && service.PushCalls == 0 && clock.Delays.Count == 1); });
        await Run("scheduler validates interval and repeated dispose cannot restart timer", async () => { var service = new ScheduledFixture(); var clock = new TestClock(); var scheduler = new WorkspaceSyncScheduler70(service, clock); await Expect("SYNC_INTERVAL", () => scheduler.StartAsync("p", true, TimeSpan.Zero)); await scheduler.StartAsync("p", true, TimeSpan.FromMinutes(1)); await scheduler.DisposeAsync(); await scheduler.DisposeAsync(); try { await scheduler.StartAsync("p", true, TimeSpan.FromMinutes(1)); throw new Exception("Expected disposed rejection"); } catch (ObjectDisposedException) { } Check(service.PushCalls == 0 && !scheduler.State.Running); });
    }
}
